-- Exercise translations (D15)
insert into public.exercise_translations
  (exercise_id, locale, name, alt_names, description, instructions, common_mistakes, media_alt)
select e.id, v.locale, v.name, v.alt_names, v.description, v.instructions, v.common_mistakes, v.media_alt
from (values
  ('abdominal-crunch', 'fr'::public.app_locale, 'Crunch abdominal', array['crunch', 'crunchs']::text[], 'Enroulement du buste au sol, de faible amplitude, qui cible les abdominaux.', '["Allonge-toi sur le dos, genoux pliés, pieds à plat au sol.","Place les mains sur la poitrine ou légèrement derrière la tête, sans tirer dessus.","Enroule le haut du dos pour décoller les omoplates du sol, en expirant.","Redescends lentement, sans reposer complètement la tête entre deux répétitions."]'::jsonb, '["Tirer sur la nuque avec les mains.","Monter trop haut en décollant le bas du dos.","Enchaîner vite avec de l’élan."]'::jsonb, 'Crunch abdominal : personne allongée sur le dos, genoux pliés, omoplates décollées du sol.'),
  ('abdominal-crunch', 'en'::public.app_locale, 'Abdominal crunch', array['crunch']::text[], 'A short curl of the upper body on the floor that targets the abs.', '["Lie on your back with knees bent and feet flat on the floor.","Place your hands on your chest or lightly behind your head, without pulling on it.","Curl your upper back to lift your shoulder blades off the floor as you breathe out.","Lower slowly, without fully resting your head between reps."]'::jsonb, '["Pulling on the neck with the hands.","Coming up so high that the lower back leaves the floor.","Rushing the reps with momentum."]'::jsonb, 'Abdominal crunch: a person lying on their back, knees bent, shoulder blades lifted off the floor.'),
  ('bodyweight-squat', 'fr'::public.app_locale, 'Squat au poids du corps', array['squat', 'squats', 'squat contrôlé']::text[], 'Flexion des jambes au poids du corps qui renforce les cuisses et les fessiers, avec un mouvement contrôlé.', '["Tiens-toi debout, pieds à la largeur des épaules, pointes légèrement tournées vers l’extérieur.","Tends les bras devant toi pour t’équilibrer et garde le buste droit.","Descends en poussant les hanches vers l’arrière et en pliant les genoux, jusqu’à avoir les cuisses environ parallèles au sol.","Pousse dans tout le pied pour remonter, en gardant les genoux dans l’axe des pieds."]'::jsonb, '["Laisser les genoux rentrer vers l’intérieur.","Décoller les talons du sol.","Arrondir le dos en bas du mouvement."]'::jsonb, 'Squat au poids du corps : personne debout, genoux pliés, cuisses parallèles au sol, bras tendus devant elle.'),
  ('bodyweight-squat', 'en'::public.app_locale, 'Bodyweight squat', array['air squat', 'controlled squat']::text[], 'A bodyweight knee bend that builds the thighs and glutes, with a controlled movement.', '["Stand with your feet shoulder-width apart, toes turned slightly out.","Reach your arms forward for balance and keep your chest up.","Lower by pushing your hips back and bending your knees until your thighs are about parallel to the floor.","Push through your whole foot to stand up, keeping your knees in line with your feet."]'::jsonb, '["Letting the knees cave inwards.","Lifting the heels off the floor.","Rounding the back at the bottom."]'::jsonb, 'Bodyweight squat: a person with knees bent, thighs parallel to the floor, arms reaching forward.'),
  ('bulgarian-split-squat', 'fr'::public.app_locale, 'Squat bulgare', array['squats bulgares', 'fente bulgare']::text[], 'Fente pied arrière surélevé qui renforce chaque jambe séparément. Les répétitions s’entendent par jambe.', '["Place-toi dos à une chaise ou un banc stable et pose le dessus du pied arrière dessus.","Avance le pied avant d’un grand pas pour que le genou reste au-dessus de la cheville en bas du mouvement.","Descends en pliant le genou avant jusqu’à ce que la cuisse soit environ parallèle au sol, buste légèrement penché.","Pousse dans le talon avant pour remonter, puis fais toutes les répétitions avant de changer de jambe."]'::jsonb, '["Placer le pied avant trop près du support.","Laisser le genou avant rentrer vers l’intérieur.","Pousser surtout avec la jambe arrière."]'::jsonb, 'Squat bulgare : personne en fente, pied arrière posé sur un banc, genou avant plié.'),
  ('bulgarian-split-squat', 'en'::public.app_locale, 'Bulgarian split squat', array['rear-foot-elevated split squat']::text[], 'A split squat with the back foot raised, building each leg on its own. Reps are per leg.', '["Stand with your back to a sturdy chair or bench and rest the top of your back foot on it.","Step your front foot far enough forward that your knee stays over your ankle at the bottom.","Lower by bending your front knee until your thigh is about parallel to the floor, chest leaning slightly forward.","Push through your front heel to come up, and finish all reps before switching legs."]'::jsonb, '["Placing the front foot too close to the support.","Letting the front knee cave inwards.","Pushing mostly with the back leg."]'::jsonb, 'Bulgarian split squat: a person in a split stance, back foot on a bench, front knee bent.'),
  ('chin-up', 'fr'::public.app_locale, 'Chin-up (supination)', array['chin-up', 'chin-ups (supination)', 'traction en supination']::text[], 'Traction mains en supination, paumes vers toi. Les biceps travaillent davantage qu’en pronation.', '["Suspends-toi à la barre, paumes tournées vers toi, mains à la largeur des épaules.","Gaine le corps et garde les jambes immobiles.","Tire en amenant la poitrine vers la barre jusqu’à passer le menton au-dessus.","Redescends lentement jusqu’à avoir les bras tendus."]'::jsonb, '["Écarter les mains trop largement, ce qui gêne les poignets.","Balancer les jambes pour monter.","Remonter avant d’avoir les bras tendus en bas."]'::jsonb, 'Chin-up (supination) : personne suspendue à une barre, paumes vers elle, menton au-dessus de la barre.'),
  ('chin-up', 'en'::public.app_locale, 'Chin-up', array['underhand pull-up', 'supinated pull-up']::text[], 'A pull-up with an underhand grip, palms facing you. The biceps work more than with an overhand grip.', '["Hang from the bar with your palms facing you, hands shoulder-width apart.","Brace your body and keep your legs still.","Pull your chest towards the bar until your chin clears it.","Lower slowly until your arms are straight."]'::jsonb, '["Placing the hands too wide, which strains the wrists.","Swinging the legs to get up.","Starting the next rep before the arms are straight at the bottom."]'::jsonb, 'Chin-up: a person hanging from a bar with palms facing them, chin above the bar.'),
  ('easy-walk', 'fr'::public.app_locale, 'Marche facile', array['marche douce', 'marche']::text[], 'Marche tranquille de récupération, sans objectif de vitesse. Elle aide à récupérer entre deux séances.', '["Marche à une allure qui te permet de parler sans effort.","Garde les épaules relâchées et laisse les bras se balancer naturellement.","Respire calmement par le nez si c’est confortable.","Arrête-toi quand tu veux : en cas de fatigue, le repos complet reste une bonne option."]'::jsonb, '["Accélérer jusqu’à transformer la marche en séance d’effort.","Rallonger la sortie au-delà du temps prévu."]'::jsonb, 'Marche facile : personne qui marche tranquillement en extérieur, bras relâchés.'),
  ('easy-walk', 'en'::public.app_locale, 'Easy walk', array['recovery walk', 'walk']::text[], 'A relaxed recovery walk with no speed target. It helps you recover between sessions.', '["Walk at a pace that lets you talk without effort.","Keep your shoulders relaxed and let your arms swing naturally.","Breathe calmly through your nose if that feels comfortable.","Stop whenever you like: if you feel tired, full rest is still a good option."]'::jsonb, '["Speeding up until the walk becomes a workout.","Going on longer than planned."]'::jsonb, 'Easy walk: a person walking calmly outdoors, arms relaxed.'),
  ('glute-bridge', 'fr'::public.app_locale, 'Pont fessier', array['ponts fessiers', 'relevé de bassin', 'glute bridge']::text[], 'Élévation du bassin au sol qui renforce les fessiers et l’arrière des cuisses, sans charger les genoux.', '["Allonge-toi sur le dos, genoux pliés, pieds à plat à la largeur des hanches, bras le long du corps.","Serre les fessiers et pousse dans les talons pour monter le bassin.","Monte jusqu’à aligner les épaules, les hanches et les genoux, et marque une courte pause.","Redescends lentement le bassin jusqu’à frôler le sol."]'::jsonb, '["Cambrer le bas du dos au lieu de serrer les fessiers.","Pousser sur la pointe des pieds.","Laisser les genoux s’écarter ou se rapprocher."]'::jsonb, 'Pont fessier : personne allongée sur le dos, pieds au sol, bassin levé et aligné avec les genoux.'),
  ('glute-bridge', 'en'::public.app_locale, 'Glute bridge', array['hip bridge', 'pont fessier']::text[], 'A hip lift from the floor that builds the glutes and hamstrings without loading the knees.', '["Lie on your back with knees bent, feet flat and hip-width apart, arms by your sides.","Squeeze your glutes and push through your heels to lift your hips.","Rise until your shoulders, hips and knees are in line, and pause briefly.","Lower your hips slowly until they nearly touch the floor."]'::jsonb, '["Arching the lower back instead of squeezing the glutes.","Pushing through the toes.","Letting the knees fall out or in."]'::jsonb, 'Glute bridge: a person lying on their back, feet on the floor, hips lifted in line with the knees.'),
  ('hanging-knee-raise', 'fr'::public.app_locale, 'Relevé de genoux suspendu', array['relevés de genoux suspendu', 'relevé de genoux', 'hanging knee raise']::text[], 'Suspendu à la barre, tu montes les genoux pour renforcer les abdominaux sans prendre d’élan.', '["Suspends-toi à la barre, bras tendus, épaules légèrement abaissées.","Stabilise le corps pour ne pas te balancer.","Monte les genoux vers la poitrine en enroulant légèrement le bassin.","Redescends les jambes lentement, sous contrôle."]'::jsonb, '["Se balancer pour monter les jambes.","Laisser retomber les jambes d’un coup.","Monter les genoux sans enrouler le bassin."]'::jsonb, 'Relevé de genoux suspendu : personne suspendue à une barre, genoux montés à hauteur des hanches.'),
  ('hanging-knee-raise', 'en'::public.app_locale, 'Hanging knee raise', array['hanging knee tuck']::text[], 'Hanging from the bar, you raise your knees to build the abs without swinging.', '["Hang from the bar with straight arms, shoulders slightly drawn down.","Steady your body so you don’t swing.","Raise your knees towards your chest, tilting your pelvis slightly up.","Lower your legs slowly, under control."]'::jsonb, '["Swinging to lift the legs.","Letting the legs drop.","Raising the knees without tilting the pelvis."]'::jsonb, 'Hanging knee raise: a person hanging from a bar, knees raised to hip height.'),
  ('long-run', 'fr'::public.app_locale, 'Sortie longue', array['course', 'course longue', 'long run']::text[], 'Course longue à allure conversationnelle, effort 5/10 ou moins. La distance prévue est un plafond, pas un objectif à battre.', '["Commence par quelques minutes de marche ou de course très lente pour t’échauffer.","Cours à une allure qui te permet de parler en phrases complètes.","Marche quelques minutes si besoin : c’est prévu et ça compte.","Arrête-toi au plus tard à la distance prévue, même si tu te sens bien.","Termine par quelques minutes de marche pour récupérer."]'::jsonb, '["Partir trop vite et transformer la sortie en contre-la-montre.","Chercher à battre son temps ou sa distance de référence.","Dépasser la distance prévue."]'::jsonb, 'Sortie longue : personne qui court tranquillement sur une route, en extérieur.'),
  ('long-run', 'en'::public.app_locale, 'Long run', array['long-distance run', 'course longue']::text[], 'A long run at a conversational pace, effort 5/10 or lower. The planned distance is a ceiling, not a target to beat.', '["Start with a few minutes of walking or very slow running to warm up.","Run at a pace that lets you speak in full sentences.","Walk for a few minutes if you need to: it’s part of the plan and it counts.","Stop at the planned distance at the latest, even if you feel good.","Finish with a few minutes of walking to recover."]'::jsonb, '["Starting too fast and turning the run into a time trial.","Trying to beat your reference time or distance.","Going past the planned distance."]'::jsonb, 'Long run: a person running easily on a road, outdoors.'),
  ('mobility-ankles', 'fr'::public.app_locale, 'Mobilité des chevilles', array['mobilité chevilles', 'chevilles']::text[], 'Mouvements doux pour garder des chevilles mobiles, importantes pour la course et les squats.', '["Debout ou assis, lève un pied et dessine des cercles lents avec la cheville, dans les deux sens.","Face à un mur, pied à environ une main du mur, avance le genou vers le mur sans décoller le talon.","Reviens, puis recommence en gardant le genou dans l’axe du pied.","Fais les deux côtés et reste dans une amplitude confortable."]'::jsonb, '["Décoller le talon quand le genou avance.","Laisser le genou partir vers l’intérieur.","Aller trop vite."]'::jsonb, 'Mobilité des chevilles : personne face à un mur, genou avancé vers le mur, talon au sol.'),
  ('mobility-ankles', 'en'::public.app_locale, 'Ankle mobility', array['ankle mobility drill', 'ankles']::text[], 'Gentle movements to keep the ankles mobile, which matters for running and squats.', '["Standing or sitting, lift one foot and draw slow circles with your ankle, in both directions.","Facing a wall with your foot about a hand’s width from it, move your knee towards the wall without lifting your heel.","Come back, then repeat, keeping your knee in line with your foot.","Do both sides and stay within a comfortable range."]'::jsonb, '["Lifting the heel as the knee moves forward.","Letting the knee drift inwards.","Going too fast."]'::jsonb, 'Ankle mobility: a person facing a wall, knee moved towards the wall, heel on the floor.'),
  ('mobility-hips', 'fr'::public.app_locale, 'Mobilité des hanches', array['mobilité hanches', 'hanches']::text[], 'Mouvements doux pour assouplir les hanches, utiles après la course et avant les séances jambes.', '["Debout, mains sur les hanches, dessine de grands cercles avec le bassin, dans un sens puis dans l’autre.","Mets-toi en fente basse, genou arrière au sol, et avance doucement le bassin jusqu’à sentir l’avant de la hanche s’étirer.","Assis au sol, jambes pliées à 90° devant et sur le côté, bascule lentement les genoux d’un côté à l’autre.","Bouge sans forcer et respire calmement ; la sensation doit rester confortable."]'::jsonb, '["Forcer l’amplitude ou faire des à-coups.","Cambrer le bas du dos dans la fente.","Retenir sa respiration."]'::jsonb, 'Mobilité des hanches : personne en fente basse, genou arrière au sol, bassin avancé.'),
  ('mobility-hips', 'en'::public.app_locale, 'Hip mobility', array['hip mobility drill', 'hips']::text[], 'Gentle movements to loosen the hips, useful after running and before leg sessions.', '["Standing with hands on your hips, draw large circles with your pelvis, one way then the other.","Kneel in a low lunge, back knee on the floor, and ease your hips forward until you feel the front of the hip stretch.","Sitting on the floor with both legs bent at 90°, one in front and one to the side, slowly rock your knees from side to side.","Move without forcing and breathe calmly; it should stay comfortable."]'::jsonb, '["Forcing the range or bouncing.","Arching the lower back in the lunge.","Holding your breath."]'::jsonb, 'Hip mobility: a person in a low lunge, back knee on the floor, hips eased forward.'),
  ('mobility-shoulders', 'fr'::public.app_locale, 'Mobilité des épaules', array['mobilité épaules', 'épaules']::text[], 'Mouvements doux pour assouplir les épaules et le haut du dos, sollicités par les tractions et les pompes.', '["Debout, bras tendus sur les côtés, fais de petits cercles qui s’agrandissent peu à peu, puis change de sens.","Dos contre un mur, bras en chandelier, fais glisser lentement les bras vers le haut puis vers le bas.","Croise un bras devant la poitrine et tiens-le doucement avec l’autre main quelques respirations.","Fais les deux côtés sans forcer ni hausser les épaules."]'::jsonb, '["Hausser les épaules vers les oreilles.","Décoller le bas du dos du mur.","Forcer l’amplitude."]'::jsonb, 'Mobilité des épaules : personne dos au mur, bras en chandelier levés contre le mur.'),
  ('mobility-shoulders', 'en'::public.app_locale, 'Shoulder mobility', array['shoulder mobility drill', 'shoulders']::text[], 'Gentle movements to loosen the shoulders and upper back, which work hard in pull-ups and push-ups.', '["Standing with arms straight out to the sides, make small circles that slowly grow, then change direction.","With your back against a wall and arms in a goalpost shape, slowly slide your arms up and down.","Bring one arm across your chest and hold it gently with the other hand for a few breaths.","Do both sides without forcing or shrugging."]'::jsonb, '["Shrugging the shoulders towards the ears.","Letting the lower back come off the wall.","Forcing the range."]'::jsonb, 'Shoulder mobility: a person with their back to a wall, arms raised in a goalpost shape against it.'),
  ('pike-push-up', 'fr'::public.app_locale, 'Pike push-up', array['pike push-ups', 'pompe pike', 'pompe en V']::text[], 'Pompe hanches hautes, en V inversé, qui oriente l’effort vers les épaules.', '["Mets-toi en position de pompe, puis recule les pieds et monte les hanches pour former un V inversé.","Garde les bras et les jambes aussi tendus que possible, la tête entre les bras.","Plie les coudes pour descendre le haut de la tête vers le sol, devant tes mains.","Pousse pour revenir bras tendus, hanches toujours hautes."]'::jsonb, '["Laisser les hanches descendre, ce qui transforme l’exercice en pompe classique.","Poser la tête au sol ou descendre trop vite.","Écarter fortement les coudes sur les côtés."]'::jsonb, 'Pike push-up : personne en V inversé, hanches hautes, mains et pieds au sol.'),
  ('pike-push-up', 'en'::public.app_locale, 'Pike push-up', array['pike press-up']::text[], 'A push-up with the hips high in an inverted V, which shifts the work to the shoulders.', '["Start in a push-up position, then walk your feet in and lift your hips into an inverted V.","Keep your arms and legs as straight as you can, head between your arms.","Bend your elbows to lower the top of your head towards the floor, just in front of your hands.","Press back up to straight arms, hips still high."]'::jsonb, '["Letting the hips drop, which turns it into a regular push-up.","Resting the head on the floor or lowering too fast.","Flaring the elbows wide to the sides."]'::jsonb, 'Pike push-up: a person in an inverted V, hips high, hands and feet on the floor.'),
  ('plank', 'fr'::public.app_locale, 'Planche', array['gainage', 'planche sur les avant-bras', 'plank']::text[], 'Gainage statique sur les avant-bras qui renforce la sangle abdominale et la stabilité du tronc.', '["Pose les avant-bras au sol, coudes sous les épaules, et tends les jambes derrière toi.","Décolle le corps pour former une ligne droite de la tête aux talons.","Serre les abdominaux et les fessiers, et respire calmement.","Tiens la position sans bouger jusqu’à la fin du temps prévu."]'::jsonb, '["Creuser le bas du dos en laissant le bassin descendre.","Monter les fesses trop haut.","Bloquer sa respiration."]'::jsonb, 'Planche : personne en appui sur les avant-bras et les pointes de pied, corps aligné.'),
  ('plank', 'en'::public.app_locale, 'Plank', array['forearm plank', 'front plank']::text[], 'A static hold on the forearms that builds the abdominal wall and trunk stability.', '["Place your forearms on the floor, elbows under your shoulders, and stretch your legs out behind you.","Lift your body into a straight line from head to heels.","Tighten your abs and glutes, and breathe steadily.","Hold still until the time is up."]'::jsonb, '["Arching the lower back by letting the hips sag.","Lifting the hips too high.","Holding your breath."]'::jsonb, 'Plank: a person supported on forearms and toes, body in a straight line.'),
  ('pull-up', 'fr'::public.app_locale, 'Traction stricte', array['traction', 'tractions strictes', 'pull-up']::text[], 'Tirage vertical au poids du corps, mains en pronation. Il renforce le dos et les bras, sans élan.', '["Suspends-toi à la barre, mains en pronation, un peu plus écartées que les épaules.","Serre les abdominaux et les fessiers pour garder le corps gainé et immobile.","Abaisse les épaules, puis tire en amenant la poitrine vers la barre jusqu’à passer le menton au-dessus.","Redescends lentement jusqu’à avoir les bras tendus, sans relâcher les épaules d’un coup."]'::jsonb, '["Prendre de l’élan avec les jambes ou le bassin.","S’arrêter à mi-hauteur au lieu de revenir bras tendus.","Tendre le cou pour passer le menton au lieu de tirer avec le dos."]'::jsonb, 'Traction stricte : personne suspendue à une barre, mains en pronation, menton au-dessus de la barre.'),
  ('pull-up', 'en'::public.app_locale, 'Pull-up', array['strict pull-up', 'traction']::text[], 'A bodyweight vertical pull with an overhand grip. It builds the back and arms, with no swinging.', '["Hang from the bar with an overhand grip, hands slightly wider than your shoulders.","Brace your abs and glutes so your body stays tight and still.","Draw your shoulders down, then pull your chest towards the bar until your chin clears it.","Lower slowly until your arms are straight, without dropping into the bottom."]'::jsonb, '["Swinging the legs or hips to build momentum.","Stopping halfway down instead of returning to straight arms.","Craning the neck to get the chin over instead of pulling with the back."]'::jsonb, 'Pull-up: a person hanging from a bar with an overhand grip, chin above the bar.'),
  ('push-up', 'fr'::public.app_locale, 'Pompe', array['pompes', 'push-up']::text[], 'Poussée horizontale au sol qui renforce la poitrine, les épaules et les triceps, corps gainé.', '["Place les mains au sol, un peu plus larges que les épaules, et tends les jambes derrière toi.","Aligne la tête, le dos et les talons, abdominaux et fessiers serrés.","Descends en pliant les coudes vers l’arrière, à environ 45° du corps, jusqu’à frôler le sol avec la poitrine.","Pousse dans le sol pour remonter bras tendus, sans casser l’alignement."]'::jsonb, '["Laisser le bassin s’affaisser ou le monter trop haut.","Écarter les coudes à 90° du corps.","Raccourcir l’amplitude au lieu de descendre près du sol."]'::jsonb, 'Pompe : personne en appui sur les mains et les pieds, corps aligné, bras tendus.'),
  ('push-up', 'en'::public.app_locale, 'Push-up', array['press-up', 'pompe']::text[], 'A horizontal push from the floor that builds the chest, shoulders and triceps, with the body braced.', '["Place your hands on the floor slightly wider than your shoulders and stretch your legs out behind you.","Line up your head, back and heels, with abs and glutes tight.","Lower by bending your elbows back at about 45° to your body until your chest nearly touches the floor.","Push the floor away to return to straight arms, keeping the line."]'::jsonb, '["Letting the hips sag or lifting them too high.","Flaring the elbows out to 90° from the body.","Cutting the range short instead of lowering close to the floor."]'::jsonb, 'Push-up: a person supported on hands and feet, body in a straight line, arms straight.'),
  ('reverse-lunge', 'fr'::public.app_locale, 'Fente arrière', array['fentes arrière', 'fente']::text[], 'Grand pas en arrière puis flexion des deux genoux, plus facile à équilibrer que la fente avant. Les répétitions s’entendent par jambe.', '["Tiens-toi debout, pieds à la largeur des hanches, mains sur les hanches.","Fais un grand pas en arrière avec une jambe et pose la pointe du pied.","Plie les deux genoux jusqu’à ce que le genou arrière frôle le sol, buste droit.","Pousse dans le talon avant pour revenir pieds joints, puis répète du même côté ou alterne."]'::jsonb, '["Faire un pas trop court, ce qui avance le genou avant.","Laisser tomber le genou arrière au sol.","Pencher le buste en avant."]'::jsonb, 'Fente arrière : personne en fente, une jambe reculée, les deux genoux pliés.'),
  ('reverse-lunge', 'en'::public.app_locale, 'Reverse lunge', array['backward lunge', 'lunge']::text[], 'A long step back then a bend of both knees, easier to balance than a forward lunge. Reps are per leg.', '["Stand with your feet hip-width apart, hands on your hips.","Take a long step back with one leg and land on the ball of your foot.","Bend both knees until your back knee nearly touches the floor, chest upright.","Push through your front heel to bring your feet together, then repeat on the same side or alternate."]'::jsonb, '["Taking too short a step, which pushes the front knee forward.","Dropping the back knee onto the floor.","Leaning the chest forward."]'::jsonb, 'Reverse lunge: a person in a lunge, one leg stepped back, both knees bent.'),
  ('side-plank', 'fr'::public.app_locale, 'Planche latérale', array['gainage latéral', 'side plank']::text[], 'Gainage sur le côté qui renforce les obliques et la stabilité du bassin. Le temps s’applique à chaque côté.', '["Allonge-toi sur le côté, avant-bras au sol, coude sous l’épaule, jambes tendues et pieds empilés.","Monte les hanches pour aligner la tête, le bassin et les pieds.","Garde le bassin face à l’avant, sans le laisser tourner ni descendre.","Tiens le temps prévu, puis change de côté."]'::jsonb, '["Laisser la hanche s’affaisser vers le sol.","Placer le coude loin de l’épaule.","Pencher le buste en avant ou en arrière."]'::jsonb, 'Planche latérale : personne sur le côté, en appui sur un avant-bras, hanches levées, corps aligné.'),
  ('side-plank', 'en'::public.app_locale, 'Side plank', array['lateral plank']::text[], 'A hold on your side that builds the obliques and pelvic stability. The time applies to each side.', '["Lie on your side with your forearm on the floor, elbow under your shoulder, legs straight and feet stacked.","Lift your hips so your head, pelvis and feet are in line.","Keep your pelvis facing forward, without letting it rotate or drop.","Hold for the set time, then switch sides."]'::jsonb, '["Letting the hip sag towards the floor.","Placing the elbow far from the shoulder.","Leaning the chest forwards or backwards."]'::jsonb, 'Side plank: a person on their side, supported on one forearm, hips lifted, body in a straight line.'),
  ('single-leg-glute-bridge', 'fr'::public.app_locale, 'Pont fessier une jambe', array['pont une jambe', 'pont fessier unilatéral']::text[], 'Pont fessier en appui sur une seule jambe, plus exigeant pour les fessiers et la stabilité du bassin. Les répétitions s’entendent par jambe.', '["Allonge-toi sur le dos, genoux pliés, pieds à plat au sol.","Tends une jambe dans le prolongement de la cuisse opposée.","Pousse dans le talon au sol pour monter le bassin, en le gardant bien horizontal.","Redescends lentement, fais toutes les répétitions puis change de jambe."]'::jsonb, '["Laisser le bassin pencher du côté de la jambe tendue.","Cambrer le bas du dos pour monter plus haut.","Prendre de l’élan avec la jambe tendue."]'::jsonb, 'Pont fessier une jambe : personne allongée sur le dos, bassin levé, une jambe tendue en l’air.'),
  ('single-leg-glute-bridge', 'en'::public.app_locale, 'Single-leg glute bridge', array['one-leg glute bridge', 'single-leg hip bridge']::text[], 'A glute bridge on one leg, harder on the glutes and on pelvic stability. Reps are per leg.', '["Lie on your back with knees bent and feet flat on the floor.","Straighten one leg in line with the opposite thigh.","Push through the heel on the floor to lift your hips, keeping them level.","Lower slowly, finish all reps, then switch legs."]'::jsonb, '["Letting the hips tilt towards the straight leg.","Arching the lower back to get higher.","Swinging the straight leg for momentum."]'::jsonb, 'Single-leg glute bridge: a person lying on their back, hips lifted, one leg straight in the air.'),
  ('standing-calf-raise', 'fr'::public.app_locale, 'Extension des mollets debout', array['extensions mollets debout', 'élévation des mollets', 'calf raise']::text[], 'Montée sur la pointe des pieds qui renforce les mollets, utiles pour la course.', '["Tiens-toi debout, pieds à la largeur des hanches, sur le sol ou la pointe des pieds au bord d’une marche.","Pose une main contre un mur pour l’équilibre si besoin.","Monte sur la pointe des pieds le plus haut possible, talons bien levés, et marque une courte pause.","Redescends lentement, talons sous le niveau de la marche si tu en utilises une."]'::jsonb, '["Monter à moitié sans lever franchement les talons.","Rebondir en bas au lieu de contrôler la descente.","Laisser les chevilles partir vers l’extérieur."]'::jsonb, 'Extension des mollets debout : personne debout sur la pointe des pieds, talons nettement levés.'),
  ('standing-calf-raise', 'en'::public.app_locale, 'Standing calf raise', array['heel raise']::text[], 'Rising onto your toes to build the calves, which helps with running.', '["Stand with your feet hip-width apart, on the floor or with the balls of your feet on the edge of a step.","Rest one hand on a wall for balance if you need to.","Rise onto your toes as high as you can, heels clearly lifted, and pause briefly.","Lower slowly, letting your heels drop below the step if you use one."]'::jsonb, '["Rising only halfway without clearly lifting the heels.","Bouncing at the bottom instead of controlling the descent.","Letting the ankles roll outwards."]'::jsonb, 'Standing calf raise: a person standing on their toes, heels clearly lifted.')
) as v (slug, locale, name, alt_names, description, instructions, common_mistakes, media_alt)
join public.exercises e on e.slug = v.slug
on conflict (exercise_id, locale) do update set
  name = excluded.name,
  alt_names = excluded.alt_names,
  description = excluded.description,
  instructions = excluded.instructions,
  common_mistakes = excluded.common_mistakes,
  media_alt = excluded.media_alt;

-- Variations and substitutes
delete from public.exercise_relations
where exercise_id in (select id from public.exercises where slug in ('abdominal-crunch', 'bodyweight-squat', 'bulgarian-split-squat', 'chin-up', 'easy-walk', 'glute-bridge', 'hanging-knee-raise', 'long-run', 'mobility-ankles', 'mobility-hips', 'mobility-shoulders', 'pike-push-up', 'plank', 'pull-up', 'push-up', 'reverse-lunge', 'side-plank', 'single-leg-glute-bridge', 'standing-calf-raise'));

insert into public.exercise_relations (exercise_id, related_exercise_id, kind)
select a.id, b.id, v.kind
from (values
  ('abdominal-crunch', 'plank', 'substitute'::public.exercise_relation_kind),
  ('bodyweight-squat', 'bulgarian-split-squat', 'substitute'::public.exercise_relation_kind),
  ('bodyweight-squat', 'reverse-lunge', 'substitute'::public.exercise_relation_kind),
  ('bulgarian-split-squat', 'bodyweight-squat', 'substitute'::public.exercise_relation_kind),
  ('bulgarian-split-squat', 'reverse-lunge', 'substitute'::public.exercise_relation_kind),
  ('chin-up', 'pull-up', 'variation'::public.exercise_relation_kind),
  ('glute-bridge', 'single-leg-glute-bridge', 'variation'::public.exercise_relation_kind),
  ('hanging-knee-raise', 'abdominal-crunch', 'substitute'::public.exercise_relation_kind),
  ('hanging-knee-raise', 'plank', 'substitute'::public.exercise_relation_kind),
  ('pike-push-up', 'push-up', 'variation'::public.exercise_relation_kind),
  ('plank', 'side-plank', 'variation'::public.exercise_relation_kind),
  ('plank', 'abdominal-crunch', 'substitute'::public.exercise_relation_kind),
  ('pull-up', 'chin-up', 'variation'::public.exercise_relation_kind),
  ('push-up', 'pike-push-up', 'variation'::public.exercise_relation_kind),
  ('reverse-lunge', 'bodyweight-squat', 'substitute'::public.exercise_relation_kind),
  ('reverse-lunge', 'bulgarian-split-squat', 'substitute'::public.exercise_relation_kind),
  ('side-plank', 'plank', 'variation'::public.exercise_relation_kind),
  ('single-leg-glute-bridge', 'glute-bridge', 'variation'::public.exercise_relation_kind),
  ('single-leg-glute-bridge', 'glute-bridge', 'substitute'::public.exercise_relation_kind)
) as v (slug, related_slug, kind)
join public.exercises a on a.slug = v.slug
join public.exercises b on b.slug = v.related_slug;

commit;
